import{_ as s,o as i,c as t,ag as a}from"./chunks/framework.C3EQwh3l.js";const u=JSON.parse('{"title":"Getting Started with Windows CoreOS (WCOS)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/Getting-Started.md","filePath":"guides/Getting-Started.md"}'),o={name:"guides/Getting-Started.md"};function n(r,e,l,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started-with-windows-coreos-wcos" tabindex="-1">Getting Started with Windows CoreOS (WCOS) <a class="header-anchor" href="#getting-started-with-windows-coreos-wcos" aria-label="Permalink to &quot;Getting Started with Windows CoreOS (WCOS)&quot;">​</a></h1><p>This guide walks you through setting up a headless <strong>Windows CoreOS (WCOS)</strong> virtual machine on an Ubuntu / Debian Linux host using QEMU/KVM, from host preparation to first automated boot and SSH access.</p><hr><h2 id="📋-system-requirements" tabindex="-1">📋 System Requirements <a class="header-anchor" href="#📋-system-requirements" aria-label="Permalink to &quot;📋 System Requirements&quot;">​</a></h2><h3 id="host-requirements-linux" tabindex="-1">Host Requirements (Linux) <a class="header-anchor" href="#host-requirements-linux" aria-label="Permalink to &quot;Host Requirements (Linux)&quot;">​</a></h3><ul><li><strong>Operating System</strong>: Ubuntu 22.04 LTS / 24.04 LTS or Debian 12 (headless server or desktop).</li><li><strong>CPU Virtualization</strong>: Intel VT-x or AMD-V enabled in host BIOS/UEFI.</li><li><strong>CPU Cores</strong>: Minimum 2 cores allocated to guest (4 recommended).</li><li><strong>RAM</strong>: Minimum 2 GB allocated to guest (4 GB recommended for heavy builds). Host needs at least 4 GB total.</li><li><strong>Disk Space</strong>: ~40 GB free space on host SSD/NVMe (QCOW2 disk is dynamic/sparse and occupies only ~12 GB initially).</li></ul><h3 id="guest-specifications" tabindex="-1">Guest Specifications <a class="header-anchor" href="#guest-specifications" aria-label="Permalink to &quot;Guest Specifications&quot;">​</a></h3><ul><li><strong>Base OS</strong>: Microsoft Hyper-V Server 2019 OEM x64 (Build 17763.737, English US).</li><li><strong>Virtualization Model</strong>: QEMU/KVM with VirtIO SCSI, VirtIO Net, VirtIO Balloon, and UEFI OVMF.</li></ul><hr><h2 id="⚡-step-by-step-installation" tabindex="-1">⚡ Step-by-Step Installation <a class="header-anchor" href="#⚡-step-by-step-installation" aria-label="Permalink to &quot;⚡ Step-by-Step Installation&quot;">​</a></h2><h3 id="step-1-clone-repository-submodules" tabindex="-1">Step 1: Clone Repository &amp; Submodules <a class="header-anchor" href="#step-1-clone-repository-submodules" aria-label="Permalink to &quot;Step 1: Clone Repository &amp; Submodules&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recurse-submodules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/samuelcaldas/windows-coreos.git</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> windows-coreos</span></span></code></pre></div><h3 id="step-2-host-environment-preparation" tabindex="-1">Step 2: Host Environment Preparation <a class="header-anchor" href="#step-2-host-environment-preparation" aria-label="Permalink to &quot;Step 2: Host Environment Preparation&quot;">​</a></h3><p>Run the automated host setup script to install QEMU, KVM, OVMF UEFI firmware, 7-Zip, <code>xorriso</code>, and configure user permissions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/host/setup-host.sh</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ensure your Linux user belongs to the <code>kvm</code> and <code>libvirt</code> groups: <code>sudo usermod -aG kvm,libvirt $USER &amp;&amp; newgrp kvm</code></p></div><hr><h3 id="step-3-download-official-microsoft-iso" tabindex="-1">Step 3: Download Official Microsoft ISO <a class="header-anchor" href="#step-3-download-official-microsoft-iso" aria-label="Permalink to &quot;Step 3: Download Official Microsoft ISO&quot;">​</a></h3><p>Windows CoreOS does NOT bundle proprietary Microsoft Windows binaries. You must obtain the official evaluation ISO from Microsoft.</p><p>You can automate the download and SHA256 verification with a single command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/host/setup-host.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --download-iso</span></span></code></pre></div><p><em>Or via PowerShell 7:</em></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DownloadIso</span></span></code></pre></div><h4 id="manual-iso-reference" tabindex="-1">Manual ISO Reference <a class="header-anchor" href="#manual-iso-reference" aria-label="Permalink to &quot;Manual ISO Reference&quot;">​</a></h4><p>If downloading manually, place the file in the <code>iso/</code> directory:</p><ul><li><strong>Filename</strong>: <code>17763.737.190906-2324.rs5_release_svc_refresh_SERVERHYPERCORE_OEM_x64FRE_en-us_1.iso</code></li><li><strong>Direct Download Link</strong>: <a href="https://software-download.microsoft.com/download/pr/17763.737.190906-2324.rs5_release_svc_refresh_SERVERHYPERCORE_OEM_x64FRE_en-us_1.iso" target="_blank" rel="noreferrer">Microsoft CDN Link</a></li><li><strong>Expected SHA256</strong>: <code>48e9b944518e5bbc80876a9a7ff99716f386f404f4be48dca47e16a66ae7872c</code></li></ul><hr><h3 id="step-4-build-unattended-provisioning-media-oemdrv-iso" tabindex="-1">Step 4: Build Unattended Provisioning Media (<code>oemdrv.iso</code>) <a class="header-anchor" href="#step-4-build-unattended-provisioning-media-oemdrv-iso" aria-label="Permalink to &quot;Step 4: Build Unattended Provisioning Media (`oemdrv.iso`)&quot;">​</a></h3><p>Run the ISO generator script to assemble the dual-drive unattended media containing <code>autounattend.xml</code>, VirtIO drivers, and first-boot bootstrap scripts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/host/build-iso.sh</span></span></code></pre></div><p>This script will:</p><ol><li>Download the latest stable Fedora VirtIO drivers ISO (<code>virtio-win.iso</code>).</li><li>Extract required storage and network drivers for Windows Server 2019 (2k19/amd64).</li><li>Download the standalone PowerShell 7 MSI (<code>PowerShell-7.x-win-x64.msi</code>).</li><li>Generate the <code>iso/oemdrv.iso</code> drive containing <code>autounattend.xml</code>.</li></ol><hr><h3 id="step-5-boot-the-virtual-machine" tabindex="-1">Step 5: Boot the Virtual Machine <a class="header-anchor" href="#step-5-boot-the-virtual-machine" aria-label="Permalink to &quot;Step 5: Boot the Virtual Machine&quot;">​</a></h3><p>Start the automated installation by launching the QEMU/KVM virtual machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/host/run-vm.sh</span></span></code></pre></div><p>During first boot:</p><ol><li>Windows Setup starts in zero-touch unattended mode.</li><li>Setup detects <code>autounattend.xml</code> on the secondary virtual drive (<code>oemdrv.iso</code>).</li><li>VirtIO SCSI storage drivers are loaded on-the-fly.</li><li>The 64 GB sparse virtual disk (<code>windows-core.qcow2</code>) is partitioned with GPT/UEFI layout.</li><li>Windows Server Core is installed, customized, and boots into PowerShell 7.</li><li>The entire process takes approximately 3 to 7 minutes depending on disk speed.</li></ol><hr><h3 id="step-6-connect-via-openssh" tabindex="-1">Step 6: Connect via OpenSSH <a class="header-anchor" href="#step-6-connect-via-openssh" aria-label="Permalink to &quot;Step 6: Connect via OpenSSH&quot;">​</a></h3><p>Once provisioning completes, OpenSSH Server is active on port <code>2222</code>. Connect directly from your Linux host:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2222</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username@127.0.0.1</span></span></code></pre></div><p><em>Default password during first boot: <code>windows</code></em></p><p>You will be greeted by the custom <strong>Windows CoreOS MOTD banner</strong> and enter a native PowerShell 7 session!</p><hr><h3 id="step-7-push-ssh-keys-remote-provisioning" tabindex="-1">Step 7: Push SSH Keys &amp; Remote Provisioning <a class="header-anchor" href="#step-7-push-ssh-keys-remote-provisioning" aria-label="Permalink to &quot;Step 7: Push SSH Keys &amp; Remote Provisioning&quot;">​</a></h3><p>Run the remote synchronization script from your Linux host to exchange ED25519 public keys and deploy developer toolchains:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/host/provision-remote.sh</span></span></code></pre></div><p>Now you can log in without entering a password:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> winvm</span></span></code></pre></div><hr><h2 id="🎯-next-steps" tabindex="-1">🎯 Next Steps <a class="header-anchor" href="#🎯-next-steps" aria-label="Permalink to &quot;🎯 Next Steps&quot;">​</a></h2><ul><li><a href="/windows-coreos/guides/System-Optimization-and-Memory-Pruning.html">System Optimization &amp; Memory Pruning</a>: Learn how WCOS drops idle RAM to ~530 MB.</li><li><a href="/windows-coreos/guides/Package-Management-with-OmniGet.html">Package Management with OmniGet</a>: Install developer tools and runtimes.</li><li><a href="/windows-coreos/guides/Host-Systemd-Autostart.html">Host Systemd Autostart</a>: Configure WCOS to start automatically on Linux host boot.</li><li><a href="/windows-coreos/guides/Autonomous-AI-Agent-Workstation.html">Autonomous AI Agent Workstation</a>: Launch Claude Code CLI and Antigravity Daemon.</li></ul>',53)])])}const g=s(o,[["render",n]]);export{u as __pageData,g as default};
